from probe import P

PROBES = [
    P("dotnet-sdk8-targets-net9", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0", "cd /tmp && dotnet new console -o w --framework net8.0 >/dev/null && sed -i 's/net8.0/net9.0/' w/w.csproj",
      "dotnet build w 2>&1", r"(error NETSDK1045:.*)",
      {"dotnet_sdk": "8.0", "target": "net9.0"}, "https://raw.githubusercontent.com/dotnet/sdk/main/src/Tasks/Common/Resources/Strings.resx",
      "NETSDK1045", "MIT", must=(r"NETSDK1045|does not support targeting", r"\.NET 9|net9\.0")),
    P("dotnet-global-json-sdk-missing", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0",
      r'''mkdir /w && cd /w && printf '{"sdk":{"version":"9.0.100","rollForward":"disable"}}' > global.json''',
      "cd /w && dotnet --version 2>&1", r"A compatible .NET SDK was not found",
      {"dotnet_sdk": "8.0", "global.json": "9.0.100"}, "https://raw.githubusercontent.com/dotnet/sdk/main/src/Tasks/Common/Resources/Strings.resx",
      "global.json", "MIT", must=(r"global\.json", r"SDK")),
    P("dotnet-runtime-version-missing", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0",
      r'''cd /tmp && dotnet new console -o w --framework net8.0 >/dev/null && dotnet build w -o /tmp/out >/dev/null && sed -i 's/"version": "8.0.[0-9]*"/"version": "9.0.0"/' /tmp/out/w.runtimeconfig.json''',
      "dotnet /tmp/out/w.dll 2>&1", r"You must install or update \.NET to run this application",
      {"dotnet_runtime": "8.0", "required": "9.0.0"}, "https://raw.githubusercontent.com/dotnet/runtime/main/src/native/corehost/error_codes.h",
      "FrameworkMissingFailure", "MIT", must=(r"Framework", r"install|update|roll-?forward|DOTNET_ROLL_FORWARD")),
    P("dotnet-no-restore-assets-missing", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0", "cd /tmp && dotnet new console -o w --no-restore >/dev/null",
      "dotnet build w --no-restore 2>&1", r"(error NETSDK1004:.*)",
      {"dotnet_sdk": "8.0"}, "https://raw.githubusercontent.com/dotnet/sdk/main/src/Tasks/Common/Resources/Strings.resx",
      "NETSDK1004", "MIT", must=(r"NETSDK1004|project\.assets\.json", r"restore")),
    P("dotnet-nuget-version-not-found", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0", "cd /tmp && dotnet new console -o w --no-restore >/dev/null",
      "cd w && dotnet add package Newtonsoft.Json --version 99.0.0 2>&1", r"(error:? .*NU1102.*|.*NU1102:.*)",
      {"dotnet_sdk": "8.0", "package": "Newtonsoft.Json"}, "https://raw.githubusercontent.com/NuGet/NuGet.Client/dev/src/NuGet.Core/NuGet.Common/Errors/NuGetLogCode.cs",
      "NU1102", "Apache-2.0", must=(r"NU1102|Unable to find package", r"version|source|nuget")),
    P("dotnet-msbuild-no-project-file", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0", "mkdir /w",
      "cd /w && dotnet build 2>&1", r"(MSB1003.*)",
      {"dotnet_sdk": "8.0"}, "https://raw.githubusercontent.com/dotnet/msbuild/main/src/MSBuild/Resources/Strings.resx",
      "MSB1003", "MIT", must=(r"MSB1003|project or solution file", r"directory|\.csproj|\.sln|cd ")),
    P("dotnet-csproj-merge-conflict-markers", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0",
      r"""cd /tmp && dotnet new console -o w --no-restore >/dev/null && sed -i 's|<PropertyGroup>|<<<<<<< HEAD\n<PropertyGroup>|' w/w.csproj""",
      "dotnet build w 2>&1", r"(error MSB4025:.*)",
      {"dotnet_sdk": "8.0"}, "https://raw.githubusercontent.com/dotnet/msbuild/main/src/Build/Resources/Strings.resx",
      "MSB4025", "MIT", must=(r"MSB4025|could not be loaded", r"conflict|XML|<<<<<<<|malformed|valid")),
    P("dotnet-cs0246-missing-package-reference", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0",
      r"""cd /tmp && dotnet new console -o w --no-restore >/dev/null && printf 'using Newtonsoft.Json;\nConsole.WriteLine(JsonConvert.SerializeObject(1));\n' > w/Program.cs""",
      "dotnet build w 2>&1", r"(error CS0(?:246|234):.*)",
      {"dotnet_sdk": "8.0"}, "https://raw.githubusercontent.com/dotnet/roslyn/main/src/Compilers/CSharp/Portable/CSharpResources.resx",
      "are you missing a using directive or an assembly reference", "MIT", must=(r"CS0246|CS0234|could not be found", r"PackageReference|dotnet add package|using|nuget")),
    P("dotnet-msbuild-more-than-one-project", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0",
      r"""cd /tmp && dotnet new console -o w --no-restore >/dev/null && cp w/w.csproj w/other.csproj""",
      "cd w && dotnet build 2>&1", r"(MSB1011.*)",
      {"dotnet_sdk": "8.0"}, "https://raw.githubusercontent.com/dotnet/msbuild/main/src/MSBuild/Resources/Strings.resx",
      "MSB1011", "MIT", must=(r"MSB1011|more than one project", r"specify|\.csproj|\.sln|dotnet build <")),
    P("dotnet-nuget-service-index-unreachable", "dotnet", "mcr.microsoft.com/dotnet/sdk:8.0",
      r"""cd /tmp && dotnet new console -o w --no-restore >/dev/null && printf '<configuration><packageSources><clear /><add key="feed" value="http://127.0.0.1:9/v3/index.json" /></packageSources></configuration>' > w/nuget.config && cd w && dotnet add package Newtonsoft.Json --no-restore >/dev/null 2>&1; sed -i 's|</Project>|<ItemGroup><PackageReference Include="Newtonsoft.Json" Version="13.0.3" /></ItemGroup></Project>|' w.csproj""",
      "cd /tmp/w && dotnet restore 2>&1", r"(error :? ?.*NU1301.*|.*NU1301:.*)",
      {"dotnet_sdk": "8.0"}, "https://raw.githubusercontent.com/NuGet/NuGet.Client/dev/src/NuGet.Core/NuGet.Common/Errors/NuGetLogCode.cs",
      "NU1301", "Apache-2.0", must=(r"NU1301|service index", r"source|feed|nuget\.config|network|proxy")),
]
